before:
Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>
#include <stdlib.h>
#if defined(__STDC_NO_THREADS__) && __STDC_NO_THREADS__
#error C threads unavailable on this implementation
#endif
#include <threads.h>
#if defined(__STDC_NO_ATOMICS__) && __STDC_NO_ATOMICS__
#error C atomics unavailable on this implementation
#endif
#include <stdatomic.h>
static atomic_int count;
static int work(void *unused) {
    (void)unused;
    for (int i = 0; i < 500; i++) atomic_fetch_add(&count, 1);
    return 0;
}
int main(void) {
    thrd_t worker;
    atomic_init(&count, 0);
    if (thrd_create(&worker, work, NULL) != thrd_success) return 1;
    for (int i = 0; i < 500; i++) atomic_fetch_add(&count, 1);
    if (thrd_join(worker, NULL) != thrd_success) abort();
    printf("%d\n", atomic_load(&count));
    return 0;
}
```

